/**
 * Zoom limits for the receipt viewer.
 *
 * 100% means fit-to-viewport, not 1:1 — so a flat maximum percentage means
 * different things on different screens. The ceiling is therefore derived from
 * the individual image: zoom stops where one image pixel fills one CSS pixel.
 * See the "Zoom never invents pixels" invariant in `docs/domain-model.md`.
 */

export interface FitDimensions {
	width: number;
	height: number;
}

/** The floor, and the meaning of "fit to viewport". */
export const MIN_ZOOM = 100;

/** Zoom in/out snap to multiples of this. */
export const ZOOM_STEP = 50;

/**
 * The size an image occupies at 100% zoom: scaled down to fit the viewport box,
 * never scaled up. An image smaller than the box is already at native size, so
 * 100% is also its ceiling.
 */
export function calculateFitDimensions(
	naturalWidth: number,
	naturalHeight: number,
	viewportWidth: number,
	viewportHeight: number
): FitDimensions {
	const scale = Math.min(viewportWidth / naturalWidth, viewportHeight / naturalHeight, 1);
	return { width: naturalWidth * scale, height: naturalHeight * scale };
}

/**
 * The zoom percentage at which the image is displayed at its true resolution —
 * the point past which further magnification would only interpolate.
 *
 * Returns MIN_ZOOM when the image is already at (or below) native size on
 * screen, which is what disables the zoom controls: there are no further real
 * pixels to show, and a greyed-out control says so honestly.
 */
export function calculateMaxZoom(naturalWidth: number, baseWidth: number): number {
	if (baseWidth <= 0) return MIN_ZOOM;
	return Math.max(MIN_ZOOM, (naturalWidth / baseWidth) * MIN_ZOOM);
}

/**
 * #{#rsz1a} #{#rsz1b} - Receipt Image Resizing
 *
 * Turns the **Source File** a person picked into the **Receipt Image** we store:
 * at most 2400px on the longest axis, JPEG at 85%, whatever arrived. The size
 * limits in `ReceiptService` describe the result of this function, not its
 * input — see `docs/adr/0006-the-stored-image-is-the-contract.md`.
 */

export interface ResizeDimensions {
	width: number;
	height: number;
}

/** Longest-axis budget for a stored Receipt Image. Chosen for human zoom, not OCR. */
export const MAX_IMAGE_DIMENSION = 2400;

/** JPEG quality for a stored Receipt Image. */
export const IMAGE_QUALITY = 0.85;

/** Every stored Receipt Image is a JPEG; only PDFs pass through untouched. */
const OUTPUT_TYPE = 'image/jpeg';

/** The image types the receipts upload control offers. */
const RESIZABLE_TYPES = ['image/jpeg', 'image/png', 'image/heic'];

/**
 * Whether a Source File of this type should be decoded and re-encoded.
 *
 * HEIC is included deliberately: Safari — the only place HEIC originates — can
 * decode it into a Canvas, and skipping it sent full-resolution phone photos
 * straight to storage. Anything else (PDFs, and image types we never offer) is
 * stored exactly as received.
 */
export function isResizableImage(mimeType: string): boolean {
	return RESIZABLE_TYPES.includes(mimeType);
}

/**
 * Rename a Source File to match the JPEG we actually store, so the storage
 * object's extension is not a lie. This never affects `original_filename`
 * (#{#ofn2a}), which keeps the name the person recognizes.
 */
export function toJpegFilename(filename: string): string {
	return filename.replace(/(\.[^./\\]*)?$/, '.jpg');
}

/**
 * #{#rsz1a} - Calculate resize dimensions maintaining aspect ratio
 *
 * Acceptance Criteria:
 * - Maximum dimension on longest axis must be MAX_IMAGE_DIMENSION
 * - Aspect ratio must be preserved during resize
 * - Images already within the budget keep original dimensions
 *
 * @param originalWidth - Original image width in pixels
 * @param originalHeight - Original image height in pixels
 * @param maxSize - Maximum dimension on longest axis
 * @returns New dimensions with preserved aspect ratio
 */
export function calculateResizeDimensions(
	originalWidth: number,
	originalHeight: number,
	maxSize: number = MAX_IMAGE_DIMENSION
): ResizeDimensions {
	const longestAxis = Math.max(originalWidth, originalHeight);

	// If image is already smaller than max, keep original dimensions
	if (longestAxis <= maxSize) {
		return { width: originalWidth, height: originalHeight };
	}

	// Calculate scale factor
	const scale = maxSize / longestAxis;

	// Calculate new dimensions (preserve aspect ratio)
	return {
		width: Math.round(originalWidth * scale),
		height: Math.round(originalHeight * scale)
	};
}

/** Promise-shaped `canvas.toBlob`, which is callback-only. */
function encodeCanvas(canvas: HTMLCanvasElement, quality: number): Promise<Blob> {
	return new Promise((resolve, reject) => {
		canvas.toBlob(
			(blob) => (blob ? resolve(blob) : reject(new Error('Failed to encode image'))),
			OUTPUT_TYPE,
			quality
		);
	});
}

/**
 * #{#rsz1a} #{#rsz1b} - Resize an image file using Canvas API
 *
 * Acceptance Criteria:
 * - JPEG, PNG and HEIC are all resized, and all come out as JPEG. PNG could not
 *   honour a quality setting while it stayed PNG — `toBlob` ignores the argument
 *   for lossless formats — so a PNG "resize" used to be able to grow the file.
 * - Resizing occurs client-side (browser) before upload
 * - Images already within the budget are still re-encoded, and so still shrink
 * - EXIF orientation is honoured (#{#rsz2b})
 * - The file is decoded ONCE. `createImageBitmap` is itself the decode; the
 *   `<img>` element this used to load first was a second full decode of the same
 *   bytes, doubling peak memory on exactly the large photos we now accept.
 *
 * Throws if the image cannot be decoded or encoded — the caller decides whether
 * that is fatal.
 *
 * @param file - Source File
 * @param maxSize - Maximum dimension on longest axis
 * @param quality - Compression quality 0-1
 * @returns The Receipt Image to store
 */
export async function resizeImage(
	file: File,
	maxSize: number = MAX_IMAGE_DIMENSION,
	quality: number = IMAGE_QUALITY
): Promise<File> {
	if (!isResizableImage(file.type)) {
		return file;
	}

	// #{#rsz2b} - createImageBitmap applies EXIF orientation as it decodes
	const bitmap = await createImageBitmap(file, { imageOrientation: 'from-image' });

	try {
		const { width, height } = calculateResizeDimensions(bitmap.width, bitmap.height, maxSize);

		const canvas = document.createElement('canvas');
		canvas.width = width;
		canvas.height = height;

		const ctx = canvas.getContext('2d');
		if (!ctx) throw new Error('Canvas context not available');
		ctx.drawImage(bitmap, 0, 0, width, height);

		const blob = await encodeCanvas(canvas, quality);

		return new File([blob], toJpegFilename(file.name), {
			type: OUTPUT_TYPE,
			lastModified: file.lastModified
		});
	} finally {
		bitmap.close();
	}
}

/**
 * ReceiptService — what the size limits actually govern.
 *
 * The limits describe the **Receipt Image** we store, not the **Source File** a
 * person handed us: validation runs after the resize, and the Source File is
 * bounded only by a memory guard. See
 * `docs/adr/0006-the-stored-image-is-the-contract.md`.
 *
 * The shared mock preamble is replicated per split file (vi.mock is hoisted
 * per-module), matching the other ReceiptService specs.
 */
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { ReceiptService } from './ReceiptService';
import { stubFetchJson, stubFetchReject } from '$lib/tests/fixtures/fetchMock';

vi.mock('$lib/supabaseClient', () => ({
	supabase: {
		auth: {
			getUser: vi.fn().mockResolvedValue({ data: { user: { id: 'test-user-id' } } })
		},
		from: vi.fn(),
		storage: { from: vi.fn() }
	}
}));

vi.mock('$lib/utils/dateValidation', () => ({ isSuspiciousDate: vi.fn(() => false) }));

vi.mock('$lib/utils/signedUrl', () => ({
	getSignedReceiptUrl: vi.fn((path: string) => Promise.resolve(`https://example.com/${path}`))
}));

vi.mock('$lib/utils/imageResize', async (importOriginal) => ({
	...(await importOriginal<typeof import('$lib/utils/imageResize')>()),
	resizeImage: vi.fn()
}));

vi.mock('./ExpenseService', () => ({
	ExpenseService: vi.fn(() => ({
		getVendorRule: vi.fn().mockResolvedValue(null),
		assignCategory: vi.fn()
	}))
}));

import { supabase } from '$lib/supabaseClient';
import { resizeImage } from '$lib/utils/imageResize';

/** A File of a stated size without allocating the bytes. */
function sourceFile(megabytes: number, name: string, type: string): File {
	const file = new File(['x'], name, { type });
	Object.defineProperty(file, 'size', { value: Math.round(megabytes * 1024 * 1024) });
	return file;
}

describe('Upload size limits govern the stored Receipt Image', () => {
	let upload: ReturnType<typeof vi.fn>;

	beforeEach(() => {
		vi.clearAllMocks();

		upload = vi.fn().mockResolvedValue({ error: null });
		(supabase.storage as { from: typeof supabase.storage.from }).from = vi
			.fn()
			.mockReturnValue({ upload }) as unknown as typeof supabase.storage.from;

		(supabase as { from: typeof supabase.from }).from = vi.fn().mockReturnValue({
			insert: vi.fn().mockReturnValue({
				select: vi.fn().mockReturnValue({
					single: vi.fn().mockResolvedValue({ data: { id: 'r1', family_id: null }, error: null })
				})
			})
		}) as unknown as typeof supabase.from;

		stubFetchReject(new Error('no ocr in test'));

		// By default the resize succeeds and produces a small JPEG.
		vi.mocked(resizeImage).mockImplementation(async (file: File) =>
			sourceFile(0.4, file.name.replace(/\.[^.]*$/, '.jpg'), 'image/jpeg')
		);
	});

	it('accepts a phone photo far over the stored-image limit, because it shrinks', async () => {
		// The reported failure: refused with "Image too large. Max 5MB." by the gate
		// standing immediately in front of the code that makes it ~400KB.
		const photo = sourceFile(11, 'IMG_4821.jpg', 'image/jpeg');

		await expect(new ReceiptService(supabase).uploadAndCreate(photo)).resolves.toBeTruthy();

		expect(resizeImage).toHaveBeenCalledOnce();
		expect(upload).toHaveBeenCalledOnce();
	});

	it('refuses an enormous Source File before attempting to decode it', async () => {
		const huge = sourceFile(40, 'panorama.jpg', 'image/jpeg');

		await expect(new ReceiptService(supabase).uploadAndCreate(huge)).rejects.toThrow(/25MB/);

		// The guard exists to protect memory, so it must fire BEFORE the decode.
		expect(resizeImage).not.toHaveBeenCalled();
	});

	it('still refuses an unsupported file type', async () => {
		const doc = sourceFile(1, 'receipt.docx', 'application/vnd.ms-word');

		await expect(new ReceiptService(supabase).uploadAndCreate(doc)).rejects.toThrow(
			/Unsupported file type/
		);
	});

	it('blames the failed shrink, not the file, when resize fails on a large photo', async () => {
		vi.mocked(resizeImage).mockRejectedValue(new Error('decode failed'));
		const photo = sourceFile(11, 'IMG_4821.heic', 'image/heic');

		await expect(new ReceiptService(supabase).uploadAndCreate(photo)).rejects.toThrow(
			/could not be shrunk/i
		);

		expect(upload).not.toHaveBeenCalled();
	});

	it('falls back to the original when resize fails but the original already fits', async () => {
		vi.mocked(resizeImage).mockRejectedValue(new Error('decode failed'));
		const small = sourceFile(2, 'receipt.png', 'image/png');

		await expect(new ReceiptService(supabase).uploadAndCreate(small)).resolves.toBeTruthy();

		expect(upload).toHaveBeenCalledOnce();
	});

	it('refuses a PDF over its own limit — PDFs are stored exactly as received', async () => {
		const pdf = sourceFile(12, 'statement.pdf', 'application/pdf');

		await expect(new ReceiptService(supabase).uploadAndCreate(pdf)).rejects.toThrow(/10MB/);

		expect(resizeImage).not.toHaveBeenCalled();
	});
});

describe('OCR is told about the file we uploaded', () => {
	beforeEach(() => {
		vi.clearAllMocks();

		(supabase.storage as { from: typeof supabase.storage.from }).from = vi.fn().mockReturnValue({
			upload: vi.fn().mockResolvedValue({ error: null })
		}) as unknown as typeof supabase.storage.from;

		(supabase as { from: typeof supabase.from }).from = vi.fn().mockReturnValue({
			insert: vi.fn().mockReturnValue({
				select: vi.fn().mockReturnValue({
					single: vi.fn().mockResolvedValue({ data: { id: 'r1', family_id: null }, error: null })
				})
			})
		}) as unknown as typeof supabase.from;

		vi.mocked(resizeImage).mockImplementation(async (file: File) =>
			sourceFile(0.4, file.name.replace(/\.[^.]*$/, '.jpg'), 'image/jpeg')
		);
	});

	it('sends the transcoded JPEG type, not the HEIC the person picked', async () => {
		const fetchMock = stubFetchJson({ data: { merchant_name: 'Costco' } });
		const heic = sourceFile(4, 'IMG_4821.heic', 'image/heic');

		await new ReceiptService(supabase).uploadAndCreate(heic);

		const body = JSON.parse(fetchMock.mock.calls[0][1].body as string);
		expect(body.mimeType).toBe('image/jpeg');
	});
});

/**
 * Zoom-limit arithmetic for the receipt viewer.
 *
 * The invariant under test is "zoom never invents pixels" (see the domain model):
 * 100% means fit-to-viewport, so the ceiling is a property of the individual
 * image rather than a fixed percentage. These are the pure calculations; the
 * component test drives the resulting button states.
 */
import { describe, it, expect } from 'vitest';
import { MIN_ZOOM, calculateFitDimensions, calculateMaxZoom } from './imageZoom';

describe('calculateFitDimensions', () => {
	it('shrinks an image larger than the viewport, preserving aspect ratio', () => {
		// 4000x3000 into a 1800x1000 box — height is the binding constraint
		const fit = calculateFitDimensions(4000, 3000, 1800, 1000);

		expect(fit.height).toBeCloseTo(1000, 5);
		expect(fit.width / fit.height).toBeCloseTo(4000 / 3000, 5);
	});

	it('uses width as the constraint for a wide image', () => {
		const fit = calculateFitDimensions(4000, 1000, 1800, 1000);

		expect(fit.width).toBeCloseTo(1800, 5);
		expect(fit.height).toBeCloseTo(450, 5);
	});

	it('never enlarges an image that already fits', () => {
		const fit = calculateFitDimensions(400, 300, 1800, 1000);

		expect(fit).toEqual({ width: 400, height: 300 });
	});

	it('leaves an image exactly the size of the viewport alone', () => {
		const fit = calculateFitDimensions(1800, 1000, 1800, 1000);

		expect(fit).toEqual({ width: 1800, height: 1000 });
	});
});

describe('calculateMaxZoom', () => {
	it('is the zoom at which one image pixel fills one CSS pixel', () => {
		// Displayed at 900px wide from a 2400px source — 1:1 arrives at 266.67%
		expect(calculateMaxZoom(2400, 900)).toBeCloseTo(266.667, 2);
	});

	it('collapses to the minimum when the image is already shown at native size', () => {
		expect(calculateMaxZoom(400, 400)).toBe(MIN_ZOOM);
	});

	it('never drops below the minimum, even if the base somehow exceeds natural', () => {
		expect(calculateMaxZoom(400, 800)).toBe(MIN_ZOOM);
	});

	it('gives a full-resolution receipt more room than a resized one', () => {
		// Same display size; the pre-resize original simply has more pixels to give.
		expect(calculateMaxZoom(4000, 900)).toBeGreaterThan(calculateMaxZoom(2400, 900));
	});

	it('reports the minimum while the natural size is still unknown', () => {
		expect(calculateMaxZoom(0, 0)).toBe(MIN_ZOOM);
	});
});

import { vi, type Mock } from 'vitest';
import type { SupabaseClient } from '@supabase/supabase-js';

/**
 * Shared chainable Supabase client mock for DI-style service specs.
 *
 * The services under test (`ExpenseService`, `CategoryService`, and any other
 * constructor-injected service) take a `SupabaseClient` and issue PostgREST-style
 * chains — `from(table).select(...).eq(...).single()` / `.upsert(...)` / a bare
 * `await from(table)...`. This builder returns a single shared query stub per client
 * where every filter/modifier method returns `this`, so the chain is order-agnostic
 * and a test only has to set `data` / `error` (or override a terminal like `single`)
 * for the path it exercises.
 *
 * This is the one canonical builder — do NOT hand-roll another `createMockSupabaseClient`
 * in a spec. It is a superset of the two shapes that previously diverged
 * (`ExpenseService`'s and `CategoryService`'s), so both suites consume it unchanged.
 *
 * NOT for the `ReceiptService.*` / reconciliation specs: those `vi.mock('$lib/supabaseClient')`
 * and wire explicit per-call chains that return *different* results across a sequence
 * (fetch original → insert split → update → delete). A single shared `mockReturnThis`
 * stub can't express that, and `vi.mock` is hoisted per-module so its preamble can't be
 * import-shared anyway. Leave those as-is.
 */
export interface MockQueryBuilder {
	data: unknown;
	error: { message: string; code?: string } | null;
	select: Mock;
	eq: Mock;
	gte: Mock;
	lte: Mock;
	ilike: Mock;
	in: Mock;
	order: Mock;
	range: Mock;
	returns: Mock;
	insert: Mock;
	update: Mock;
	delete: Mock;
	upsert: Mock;
	single: Mock;
	then: Mock;
}

/** Retrieve the query stub behind `client.from(table)` with its mock surface exposed. */
export function getMockQuery(client: SupabaseClient, table: string): MockQueryBuilder {
	return client.from(table) as unknown as MockQueryBuilder;
}

/** Replace what the mocked `client.from()` returns for subsequent calls. */
export function setFromResult(client: SupabaseClient, builder: object): void {
	(client.from as unknown as Mock).mockReturnValue(builder);
}

/**
 * Build a chainable Supabase client mock with a single shared query stub.
 *
 * `single()` and the thenable `then()` both read the stub's live `data` / `error`
 * (so a test sets `getMockQuery(client, table).data = …` once); `single()` also unwraps
 * a non-empty array to its first element, mirroring PostgREST's single-row semantics.
 */
export function createMockSupabaseClient(): SupabaseClient {
	const mockQuery = {
		data: null as unknown,
		error: null as { message: string; code?: string } | null,
		select: vi.fn().mockReturnThis(),
		eq: vi.fn().mockReturnThis(),
		gte: vi.fn().mockReturnThis(),
		lte: vi.fn().mockReturnThis(),
		ilike: vi.fn().mockReturnThis(),
		in: vi.fn().mockReturnThis(),
		order: vi.fn().mockReturnThis(),
		range: vi.fn().mockReturnThis(),
		returns: vi.fn().mockReturnThis(),
		insert: vi.fn().mockReturnThis(),
		update: vi.fn().mockReturnThis(),
		delete: vi.fn().mockReturnThis(),
		upsert: vi.fn().mockResolvedValue({ data: null, error: null }),
		single: vi.fn(function (this: MockQueryBuilder) {
			// PostgREST single-row: unwrap a non-empty array to its first element.
			if (Array.isArray(this.data) && this.data.length > 0) {
				return Promise.resolve({ data: this.data[0], error: this.error });
			}
			return Promise.resolve({ data: this.data, error: this.error });
		}),
		then: vi.fn(function (this: MockQueryBuilder, resolve: (value: unknown) => unknown) {
			// Make the query object awaitable for `const { data, error } = await from()...`.
			return resolve({ data: this.data, error: this.error });
		})
	};

	return {
		from: vi.fn().mockReturnValue(mockQuery),
		rpc: vi.fn().mockResolvedValue({ data: null, error: null }),
		auth: {
			getUser: vi.fn().mockResolvedValue({ data: { user: { id: 'test-user-id' } }, error: null }),
			getSession: vi.fn().mockResolvedValue({ data: { session: { user: { id: 'test-user-id' } } } })
		}
	} as unknown as SupabaseClient;
}
=====FETCHMOCK
import { vi, type Mock } from 'vitest';

/**
 * Shared `globalThis.fetch` stubbing for specs that exercise a code path issuing a
 * single `fetch` (Bank of Canada rates in `ExchangeRateService`, the OCR endpoint in
 * `ReceiptService`). Centralises the `{ ok, json }` Response shape and the
 * `as unknown as typeof fetch` cast so a spec says what the endpoint returns, not how
 * to fake a Response.
 */

/** Minimal Response-like stub with a JSON body. `status` defaults from `ok`. */
export function jsonResponse(
	body: unknown,
	{ ok = true, status }: { ok?: boolean; status?: number } = {}
) {
	return { ok, status: status ?? (ok ? 200 : 500), json: () => Promise.resolve(body) };
}

/**
 * Replace `globalThis.fetch` with a mock resolving `body` as JSON and return the mock
 * (for `expect(...).toHaveBeenCalledWith(...)`). Pair with {@link installFetchMock} to
 * restore the real fetch afterwards.
 */
export function stubFetchJson(body: unknown, opts?: { ok?: boolean; status?: number }): Mock {
	const mock = vi.fn().mockResolvedValue(jsonResponse(body, opts));
	globalThis.fetch = mock as unknown as typeof fetch;
	return mock;
}

/** Replace `globalThis.fetch` with a rejecting mock (network error) and return it. */
export function stubFetchReject(error: Error = new Error('Network error')): Mock {
	const mock = vi.fn().mockRejectedValue(error);
	globalThis.fetch = mock as unknown as typeof fetch;
	return mock;
}

/**
 * Save the current `globalThis.fetch` and return a `restore()` that puts it back.
 * Call in `beforeEach`, invoke the result in `afterEach`.
 */
export function installFetchMock(): () => void {
	const original = globalThis.fetch;
	return () => {
		globalThis.fetch = original;
	};
}
=====APPMOCKS
/**
 * Route/layout render harness — controllable mocks for the SvelteKit + Supabase
 * module boundaries a `+page.svelte` / `+layout.svelte` touches on mount.
 *
 * Why this exists: route components import `$app/stores` (the `page` store) and
 * `$lib/supabaseClient` (a module-level Supabase singleton created at import time,
 * which throws / hits the network in a test). Both must be replaced before the
 * component is imported. A spec wires them up once at the top:
 *
 *     import { pageStore, supabaseMock, setRoute, setSession, resetHarness }
 *         from '$lib/tests/harness/appMocks';
 *     vi.mock('$app/stores', () => ({ page: pageStore }));
 *     vi.mock('$lib/supabaseClient', () => ({ supabase: supabaseMock }));
 *     beforeEach(resetHarness);
 *
 * A spec that renders `+layout.svelte` needs a third: `$lib/dev/autoLogin`. It
 * reads `PUBLIC_SUPABASE_URL` from `$env/static/public`, which vitest does not
 * set, so importing it for real fails at module load with "does not provide an
 * export named PUBLIC_SUPABASE_URL" — mocking `$lib/supabaseClient` does not
 * cover it, because it is a separate importer of the same virtual module.
 *
 *     vi.mock('$lib/dev/autoLogin', () => ({ autoLoginForDev: async () => {} }));
 *
 * Then each test drives state with setRoute()/setSession() BEFORE render().
 *
 * These are hand-built (not the real client) so tests stay pure — no network, no
 * env, no auth/seed harness. See docs/product-backlog.md → Test-suite cleanup.
 */
import { writable } from 'svelte/store';
import type { Session } from '@supabase/supabase-js';
import type { ReceiptRow } from '$lib/models/Receipt';
import type { Expense } from '$lib/services/ExpenseService';
import type { Category } from '$lib/types/Category';
import type { CategoryGroup } from '$lib/types/Hierarchy';
import type { FamilyMember } from '$lib/utils/familyMembers';

/** Minimal shape the layout/pages read off the `page` store: `$page.url`. */
interface PageState {
	url: URL;
}

/** Live `page` store — a real Svelte store, so `$page` works in the component. */
export const pageStore = writable<PageState>({ url: new URL('http://localhost/') });

/** Point the harness at a route. `search` is an optional `?a=b` query string. */
export function setRoute(pathname: string, search = ''): void {
	pageStore.set({ url: new URL(`http://localhost${pathname}${search}`) });
}

// --- Supabase auth mock -------------------------------------------------------
// The layout subscribes via onAuthStateChange and then awaits getSession(). We
// keep the current session in a closure and notify subscribers on setSession().

type AuthCallback = (event: string, session: Session | null) => void;

let currentSession: Session | null = null;
let sessionPending = false;
const authSubscribers = new Set<AuthCallback>();

/**
 * Set (or clear) the signed-in session and notify auth subscribers, mirroring a
 * real login/logout. Call BEFORE render() to choose the authed/unauthed path.
 */
export function setSession(session: Session | null): void {
	currentSession = session;
	for (const cb of authSubscribers) cb(session ? 'SIGNED_IN' : 'SIGNED_OUT', session);
}

/** Build a minimal session object for a signed-in user. */
export function fakeSession(userId = 'test-user-id'): Session {
	return {
		user: { id: userId, email: 'primary@example.com', created_at: '2026-01-01T00:00:00Z' }
	} as unknown as Session;
}

/**
 * Make getSession() hang, so the layout stays in its pre-auth-check "Loading…"
 * state. Use to assert what a user sees before the session resolves.
 */
export function setSessionPending(): void {
	sessionPending = true;
}

// --- profiles table mock -----------------------------------------------------
// The profile page reads/writes supabase.from('profiles') directly (no service).
// setProfile() controls what the select().eq().single() chain returns; writes
// (insert/update) succeed inertly. A null profile yields the PGRST116 "no rows"
// error the page treats as "no profile yet".

/** A row of the `profiles` table (primary email lives in auth, not here). */
