// #{#ofn3a} Sanitize a user- or email-supplied filename before storing it.
// Display-only — never re-used as a filesystem path or storage key.

const MAX_LENGTH = 255;
// eslint-disable-next-line no-control-regex -- stripping control characters is the intent
const STRIP_CHARS = /[/\\\x00-\x1f\x7f]/g;
const WHITESPACE_RUN = /\s+/g;

export function sanitizeFilename(input: string | null | undefined): string | null {
	if (input == null) return null;

	const cleaned = input.replace(STRIP_CHARS, '').replace(WHITESPACE_RUN, ' ').trim();

	if (cleaned.length === 0) return null;
	if (cleaned.length <= MAX_LENGTH) return cleaned;

	return truncatePreservingExtension(cleaned, MAX_LENGTH);
}

// #{#ofn2c} Build the display filename for receipts ingested from email body text.
export function formatEmailSubjectAsFilename(subject: string | null | undefined): string {
	const sanitizedSubject = sanitizeFilename(subject);
	const body = sanitizedSubject ?? '(no subject)';
	const candidate = `email: ${body}`;
	return sanitizeFilename(candidate) ?? 'email: (no subject)';
}

function truncatePreservingExtension(name: string, max: number): string {
	const dot = name.lastIndexOf('.');
	// Treat as extension only if the dot isn't the first char and the suffix is short enough to leave room
	if (dot > 0 && dot < name.length - 1) {
		const ext = name.slice(dot);
		if (ext.length < max) {
			return name.slice(0, max - ext.length) + ext;
		}
	}
	return name.slice(0, max);
}
